<?php
require 'config.php';require 'includes/functions.php';need_role(['patient']);verify();
$doctors=$pdo->query("SELECT d.id,d.specialty,d.consultation_fee,u.name doctor_name,h.name hospital_name FROM doctors d JOIN users u ON u.id=d.user_id JOIN hospitals h ON h.id=d.hospital_id WHERE d.active=1 AND h.active=1 ORDER BY u.name")->fetchAll();$selected=(int)($_GET['doctor']??$_POST['doctor_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){$doc=(int)$_POST['doctor_id'];$date=$_POST['date']??'';$time=$_POST['time']??'';$reason=trim($_POST['reason']??'');$valid=false;foreach($doctors as $d)if($d['id']===$doc)$valid=true;
 if(!$valid||strtotime($date)<strtotime(date('Y-m-d'))||!preg_match('/^(09|1[0-7]):(00|30)$/',$time)||!available($pdo,$doc,$date,$time))flash('Please choose a valid available date and time.','error');
 else{$q=$pdo->prepare("INSERT INTO appointments(patient_id,doctor_id,appointment_date,appointment_time,reason,status) VALUES(?,?,?,?,?,'pending')");$q->execute([user()['id'],$doc,$date,$time,$reason]);flash('Appointment request submitted. Check your dashboard for status.');go('dashboard.php');}}
$title='Book appointment';require 'includes/header.php';?>
<div class="formbox wide"><span class="tag">BOOK A VISIT</span><h1>Schedule an appointment</h1><p>Choose a doctor and available appointment slot. Demo hours: 09:00–17:30.</p><form method="post"><?=csrf()?><label>Doctor<select name="doctor_id" required><option value="">Select doctor</option><?php foreach($doctors as $d):?><option value="<?=$d['id']?>" <?=$selected===$d['id']?'selected':''?>>Dr. <?=e($d['doctor_name'])?> · <?=e($d['specialty'])?> · <?=e($d['hospital_name'])?></option><?php endforeach;?></select></label><div class="two"><label>Date<input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><label>Time<select name="time" required><option value="">Select time</option><?php for($h=9;$h<=17;$h++)foreach([0,30] as $m):?><option value="<?=sprintf('%02d:%02d',$h,$m)?>"><?=sprintf('%02d:%02d',$h,$m)?></option><?php endforeach;?></select></label></div><label>Reason for visit (avoid sensitive details in this demo)<textarea name="reason" rows="3" maxlength="500"></textarea></label><button class="btn full">Submit appointment request</button></form></div><?php require 'includes/footer.php';?>